static const char policy_head[] =
 "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
 "<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n"
 "<plist version=\"1.0\"><dict>";
static const char policy_watchdogd[]="<key>com.apple.watchdogd</key><true/>";
// Bring-up isolation: hardware stacks show identityservicesd, contextstored and locationd in a
// cycle of synchronous XPC waits. A disabled job makes its Mach service lookups fail instead of hang.
// sheng-disable-jobs=<label>[,<label>...] (restricted label characters, bounded length).
static const char policy_tail[]="</dict></plist>\n";
// sheng-lite=1: jobs that only reach for the network, iCloud or the photo library and have nothing to do on this tablet (no radios, no accounts),
// all of which start at the first boot of a fresh Data and compete with SpringBoard for the CPU and for memory. The first four are the
// cycle of synchronous XPC waits the isolation work found. Labels are the ones in the target's own LaunchDaemons.
static const char lite_jobs[]=
 "com.apple.identityservicesd,com.apple.locationd,com.apple.CommCenter,com.apple.bluetoothd,"
 "com.apple.photoanalysisd,com.apple.mediaanalysisd,com.apple.mediastream.mstreamd,com.apple.icloud.searchpartyd,"
 "com.apple.findmy.findmybeaconingd,com.apple.familycircled,com.apple.financed,com.apple.softwareupdateservicesd,"
 "com.apple.ndoagent,com.apple.biomesyncd,com.apple.email.maild,com.apple.amsengagementd,com.apple.adid,com.apple.eyereliefd,"
 // Crash or respawn loops seen on hardware (int-176): fairplayd.A2 is KeepAlive and exits at once (22 launches in 6 minutes), passd crashes,
 // obliteration is a data-wipe daemon with nothing to do here. iconservicesagent also dies in CI::GLContext::init, but disabling it leaves
 // the icons missing (seen on hardware), so it stays enabled.
 "com.apple.fairplayd.A2,com.apple.passd,com.apple.mobile.obliteration";
static char policy[2048],jobs[200];
volatile int sheng_watchdog_policy_status=-1;

// sheng-setup=1 or sheng-data-reset=2 (the install entry's "show Hello" choice): remove Setup's completion flags once, so this boot shows the Hello page.
// iPadOS writes them again when Setup finishes, so later boots do not show it. Absent files are fine.
static int sheng_boot_setup_reset(proc_t p,uint64_t scratch) {
 static const char *const files[]={
  "/private/var/mobile/Library/Preferences/com.apple.purplebuddy.plist",
  "/private/var/mobile/Library/Preferences/com.apple.purplebuddy.notbackedup.plist"};
 for(unsigned i=0;i<sizeof(files)/sizeof(files[0]);++i) {
  int32_t result=0;
  int error=copyout(files[i],scratch,strlen(files[i])+1);
  if(error)return error;
  struct unlink_args rm={.path=scratch};
  error=unlink(p,&rm,&result);
  if(error && error!=ENOENT)return error;
 }
 return 0;
}

// sheng-keychains=1: /private/var/Keychains for securityd (uid 64 _securityd, gid 0, 0755) when the Data seed lacks it.
// securityd cannot create it itself under root-owned /private/var, so without it no keychain item can be stored or queried.
static int sheng_boot_keychains(proc_t p,uint64_t scratch) {
 int on=0;int32_t result=0;
 if(!PE_parse_boot_argn("sheng-keychains",&on,sizeof(on)) || on!=1)return 0;
 const char *dir="/private/var/Keychains";
 int error=copyout(dir,scratch,strlen(dir)+1);
 if(error)return error;
 struct mkdir_args md={.path=scratch,.mode=0755};
 error=mkdir(p,&md,&result);
 int created=!error;
 if(error && error!=EEXIST)return error;
 struct lchown_args own={.path=scratch,.owner=64,.group=0};
 error=lchown(p,&own,&result);
 if(!error){struct chmod_args cm={.path=scratch,.mode=0755};error=chmod(p,&cm,&result);}
 printf("sheng keychains: %s rc %d\n",created?"created":"existing",error);
 return error;
}

// sheng-data-skel=1: the OS volume's /private/var template (DataSkel21H16.h, generated by mkskel.py from the 21H16 OS image), which a
// first-install Data seed carries (scripts/make-data-seed.py copies it) and the scratch seed lacks: daemons that expect their directories
// (PerfPowerService, ScreenTimeAgent data vaults, securityd's Keychains) fail without them. Directories get the template owner and mode;
// the symlink and the small files are only created when absent. Errors are counted and reported, never fatal.
#include "DataSkel21H16.h"
static int sheng_boot_data_skel(proc_t p,uint64_t scratch) {
 int on=0;int32_t result=0;
 if(!PE_parse_boot_argn("sheng-data-skel",&on,sizeof(on)) || on!=1)return 0;
 unsigned created=0,fixed=0,files=0,links=0,failed=0;int last=0;
 for(unsigned i=0;i<sizeof(sheng_skel_21h16)/sizeof(sheng_skel_21h16[0]);++i) {
  const struct sheng_skel_entry *e=&sheng_skel_21h16[i];
  int error=copyout(SKEL_PATH(e),scratch,strlen(SKEL_PATH(e))+1);
  if(!error && e->kind==0) {
   struct mkdir_args md={.path=scratch,.mode=e->mode};
   error=mkdir(p,&md,&result);
   if(!error)++created; else if(error==EEXIST){error=0;++fixed;}
   if(!error){struct lchown_args own={.path=scratch,.owner=e->uid,.group=e->gid};error=lchown(p,&own,&result);}
   if(!error){struct chmod_args cm={.path=scratch,.mode=e->mode};error=chmod(p,&cm,&result);}
  } else if(!error && e->kind==1) {
   error=copyout(SKEL_DATA(e),scratch+0x200,(size_t)e->size+1);
   if(!error){struct symlink_args sl={.path=scratch+0x200,.link=scratch};error=symlink(p,&sl,&result);}
   if(!error){++links;struct lchown_args own={.path=scratch,.owner=e->uid,.group=e->gid};error=lchown(p,&own,&result);}
   else if(error==EEXIST)error=0;
  } else if(!error && e->kind==2) {
   struct open_args op={.path=scratch,.flags=O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW,.mode=e->mode};
   error=open(p,&op,&result);
   if(error==EEXIST){error=0;continue;}
   if(!error) {
    int fd=result;
    for(size_t sent=0;!error && sent<e->size;) {
     size_t piece=e->size-sent<0x1f0?e->size-sent:0x1f0;
     error=copyout(SKEL_DATA(e)+sent,scratch+0x200,piece);
     if(!error){struct write_args wr={.fd=fd,.cbuf=scratch+0x200,.nbyte=piece};user_ssize_t written=0;error=write(p,&wr,&written);
      if(!error && written!=(user_ssize_t)piece)error=EIO;}
     sent+=piece;
    }
    if(!error){struct fchown_args own={.fd=fd,.uid=e->uid,.gid=e->gid};error=fchown(p,&own,&result);}
    if(!error){struct fchmod_args cm={.fd=fd,.mode=e->mode};error=fchmod(p,&cm,&result);}
    struct close_args cl={.fd=fd};int ce=sys_close(p,&cl,&result);if(!error)error=ce;
    if(!error)++files;
   }
  }
  if(error){++failed;last=error;}
 }
 printf("sheng data skel: dirs created %u existing %u, files %u, links %u, failed %u (last %d)\n",created,fixed,files,links,failed,last);
 return failed?last:0;
}

// With sheng-data-skel=1 (no boot-arg room for a switch of its own): a managed DictationLanguagesEnabled for the keyboard. With no Setup run, the key is absent; this device reports
// no dictation support, so -[UIKeyboardInputModeController updateEnabledDictationLanguages:] never stores one, and every
// -[UIKeyboardInputMode dictationLanguage] (each keyboard layout, each AFDictationConnection availability callback) falls into it and
// recomputes every input mode through TextInput (TIGetDefaultInputModesForLanguage): the app's main thread at 100 % while typing
// (zz-hot-sampler inclusive frames, 2026-11-13). The managed layer only answers reads of this key and leaves the user's own
// com.apple.Preferences alone; the file is rewritten at every boot. Keys: every spelling of the English and Chinese languages a
// keyboard may report (a missing one takes the slow path again; the user switched the system language on 2026-11-14).
static const char dictation_body[] =
  "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
  "<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n"
// fuxi 2026-11-18 K3: values false, so isDictationLanguageEnabled: stops before dictationIsAvailableForLanguage: (AFPreferences per call).
  "<plist version=\"1.0\"><dict><key>DictationLanguagesEnabled</key><dict>"
// fuxi 2026-11-18 K6: every iOS 17 dictation locale in both spellings: K5 (after the K4S wipe) still called updateEnabledDictationLanguages:,
// which runs only when the queried language is not one of these keys (isDictationLanguageEnabled: allKeys containsObject:).
  "<key>ar-AE</key><false/><key>ar_AE</key><false/><key>ar-SA</key><false/><key>ar_SA</key><false/><key>ca-ES</key><false/><key>ca_ES</key><false/><key>cs-CZ</key><false/><key>cs_CZ</key><false/><key>da-DK</key><false/><key>da_DK</key><false/><key>de-AT</key><false/><key>de_AT</key><false/><key>de-CH</key><false/><key>de_CH</key><false/><key>de-DE</key><false/><key>de_DE</key><false/><key>el-GR</key><false/><key>el_GR</key><false/><key>en-AE</key><false/><key>en_AE</key><false/><key>en-AU</key><false/><key>en_AU</key><false/><key>en-CA</key><false/><key>en_CA</key><false/><key>en-CN</key><false/><key>en_CN</key><false/><key>en-GB</key><false/><key>en_GB</key><false/><key>en-ID</key><false/><key>en_ID</key><false/><key>en-IE</key><false/><key>en_IE</key><false/><key>en-IN</key><false/><key>en_IN</key><false/><key>en-NZ</key><false/><key>en_NZ</key><false/><key>en-PH</key><false/><key>en_PH</key><false/><key>en-SA</key><false/><key>en_SA</key><false/><key>en-SG</key><false/><key>en_SG</key><false/><key>en-US</key><false/><key>en_US</key><false/><key>en-ZA</key><false/><key>en_ZA</key><false/><key>es-CL</key><false/><key>es_CL</key><false/><key>es-CO</key><false/><key>es_CO</key><false/><key>es-ES</key><false/><key>es_ES</key><false/><key>es-MX</key><false/><key>es_MX</key><false/><key>es-US</key><false/><key>es_US</key><false/><key>fi-FI</key><false/><key>fi_FI</key><false/><key>fr-BE</key><false/><key>fr_BE</key><false/><key>fr-CA</key><false/><key>fr_CA</key><false/><key>fr-CH</key><false/><key>fr_CH</key><false/><key>fr-FR</key><false/><key>fr_FR</key><false/><key>he-IL</key><false/><key>he_IL</key><false/><key>hi-IN</key><false/><key>hi_IN</key><false/><key>hr-HR</key><false/><key>hr_HR</key><false/><key>hu-HU</key><false/><key>hu_HU</key><false/><key>id-ID</key><false/><key>id_ID</key><false/><key>it-CH</key><false/><key>it_CH</key><false/><key>it-IT</key><false/><key>it_IT</key><false/><key>ja-JP</key><false/><key>ja_JP</key><false/><key>ko-KR</key><false/><key>ko_KR</key><false/><key>ms-MY</key><false/><key>ms_MY</key><false/><key>nb-NO</key><false/><key>nb_NO</key><false/><key>nl-BE</key><false/><key>nl_BE</key><false/><key>nl-NL</key><false/><key>nl_NL</key><false/><key>pl-PL</key><false/><key>pl_PL</key><false/><key>pt-BR</key><false/><key>pt_BR</key><false/><key>pt-PT</key><false/><key>pt_PT</key><false/><key>ro-RO</key><false/><key>ro_RO</key><false/><key>ru-RU</key><false/><key>ru_RU</key><false/><key>sk-SK</key><false/><key>sk_SK</key><false/><key>sv-SE</key><false/><key>sv_SE</key><false/><key>th-TH</key><false/><key>th_TH</key><false/><key>tr-TR</key><false/><key>tr_TR</key><false/><key>uk-UA</key><false/><key>uk_UA</key><false/><key>vi-VN</key><false/><key>vi_VN</key><false/><key>wuu-CN</key><false/><key>wuu_CN</key><false/><key>yue-CN</key><false/><key>yue_CN</key><false/><key>zh-CN</key><false/><key>zh_CN</key><false/><key>zh-HK</key><false/><key>zh_HK</key><false/><key>zh-TW</key><false/><key>zh_TW</key><false/><key>en</key><false/><key>zh</key><false/><key>zh-Hans</key><false/><key>zh_Hans</key><false/><key>zh-Hant</key><false/><key>zh_Hant</key><false/><key>zh-Hans-CN</key><false/><key>zh-Hans_CN</key><false/><key>zh_Hans_CN</key><false/><key>zh_Hans-CN</key><false/><key>zh-Hant-TW</key><false/><key>zh-Hant_TW</key><false/><key>zh-Hant-HK</key><false/><key>zh-Hant_HK</key><false/><key>yue-Hant-CN</key><false/><key>yue-Hant_CN</key><false/><key>yue_Hant_CN</key><false/><key>ja</key><false/><key>ko</key><false/><key>fr</key><false/><key>de</key><false/><key>es</key><false/><key>it</key><false/><key>ru</key><false/><key>pt</key><false/><key>ar</key><false/>"
  "</dict></dict></plist>\n";
// copyin lands here: scratch is a user address and cannot be read directly.
static char dictation_rbuf[sizeof(dictation_body)];
// Same bytes as the writer above, compared by hand so this needs no string header.
static int fuxi_same_bytes(const char *a,const char *b,unsigned n) {
 for(unsigned i=0;i<n;++i)if(a[i]!=b[i])return 0;
 return 1;
}

// Removes the two managed plists only when they are still exactly the body this file writes. The
// writer used O_TRUNC, so an identical file is ours alone; a different one may carry other managed
// settings and is left in place (reported as kept). Reading sizeof(body) bytes and expecting one
// less proves the file ends there instead of merely starting with our text.
// No copyout to scratch+0x200 happens here, so the scratch+0x400 cache-mount slot is untouched.
static int fuxi_boot_dictation_cleanup(proc_t p,uint64_t scratch) {
 int on=0;int32_t result=0;
 if(!PE_parse_boot_argn("sheng-data-skel",&on,sizeof(on)) || on!=1)return 0;
 static const char *const paths[]={
  "/private/var/Managed Preferences/mobile/com.apple.Preferences.plist",
  "/private/var/Managed Preferences/mobile/com.apple.keyboard.preferences.plist"};
 int last=0,removed=0,kept=0,absent=0;
 for(unsigned i=0;i<sizeof(paths)/sizeof(paths[0]);++i) {
  int error=copyout(paths[i],scratch,strlen(paths[i])+1);
  struct open_args op={.path=scratch,.flags=O_RDONLY|O_NOFOLLOW,.mode=0};
  if(!error)error=open(p,&op,&result);
  if(!error) {
   int fd=result;int ours=0;
   struct read_args rd={.fd=fd,.cbuf=scratch+0x200,.nbyte=sizeof(dictation_body)};
   user_ssize_t n=0;error=read(p,&rd,&n);
   if(!error && n==(user_ssize_t)(sizeof(dictation_body)-1)) {
    error=copyin(scratch+0x200,dictation_rbuf,sizeof(dictation_body)-1);
    if(!error)ours=fuxi_same_bytes(dictation_rbuf,dictation_body,sizeof(dictation_body)-1);
   }
   struct close_args cl={.fd=fd};int ce=sys_close(p,&cl,&result);if(!error)error=ce;
   if(!error && ours) {
    error=copyout(paths[i],scratch,strlen(paths[i])+1);
    if(!error){struct unlink_args ul={.path=scratch};error=unlink(p,&ul,&result);}
    if(!error)++removed; else ++kept;
   } else if(!error) ++kept;
  } else if(error==ENOENT) {error=0;++absent;}
  if(error)last=error;
 }
 printf("fuxi dictation cleanup: removed %d kept %d absent %d rc %d\n",removed,kept,absent,last);
 return last;
}

// Keyboard lag C group (2026-11-17): stop the AFDictationConnection availability callbacks at the
// source instead of feeding DictationLanguagesEnabled. The dictation master switch lives in
// com.apple.assistant.support ("Dictation Enabled"; Siri is "Assistant Enabled"). The 2026-11-15 log shows
// cfprefsd looking for the managed copy of that domain and getting ENOENT at every keyboard bring-up, so a
// managed file answers the read with "off" and UIKeyboardInputMode stops asking for dictation availability.
// Default on with sheng-data-skel=1; sheng-dictation-off=0 skips it for an A/B image. A separate file from
// the two the B-group cleanup removes, so the cleanup never touches it. Rewritten every boot.
static const char dictation_off_body[] =
  "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
  "<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n"
  "<plist version=\"1.0\"><dict>"
  "<key>Dictation Enabled</key><false/>"
  "<key>Assistant Enabled</key><false/>"
  "<key>Siri Data Sharing Opt-In Status</key><integer>2</integer>"
  "</dict></plist>\n";
static int fuxi_boot_dictation_off(proc_t p,uint64_t scratch) {
 int on=0,off=1;int32_t result=0;
 if(!PE_parse_boot_argn("sheng-data-skel",&on,sizeof(on)) || on!=1)return 0;
 PE_parse_boot_argn("sheng-dictation-off",&off,sizeof(off));
 if(off!=1){printf("fuxi dictation off: skipped\n");return 0;}
 static const char path[]="/private/var/Managed Preferences/mobile/com.apple.assistant.support.plist";
 int error=copyout(path,scratch,sizeof(path));
 int fd=-1;
 if(!error){struct open_args op={.path=scratch,.flags=O_WRONLY|O_CREAT|O_TRUNC|O_NOFOLLOW,.mode=0644};error=open(p,&op,&result);if(!error)fd=result;}
 if(!error)error=copyout(dictation_off_body,scratch+0x200,sizeof(dictation_off_body)-1);
 if(!error){struct write_args wr={.fd=fd,.cbuf=scratch+0x200,.nbyte=sizeof(dictation_off_body)-1};user_ssize_t n=0;error=write(p,&wr,&n);
  if(!error && n!=(user_ssize_t)(sizeof(dictation_off_body)-1))error=EIO;}
 if(!error){struct fchown_args own={.fd=fd,.uid=0,.gid=0};error=fchown(p,&own,&result);}
 if(fd>=0){struct close_args cl={.fd=fd};int ce=sys_close(p,&cl,&result);if(!error)error=ce;}
 printf("fuxi dictation off: managed assistant.support rc %d\n",error);
 return error;
}

static int fuxi_boot_dictation_prefs(proc_t p,uint64_t scratch) {
 // Keyboard lag B group (2026-11-16): the managed DictationLanguagesEnabled experiment is
 // withdrawn by default. It never stopped the updateEnabledDictationLanguages loop (input stayed
 // slow with all 21 keys present), and stopping the write does not remove what earlier boots put
 // on Data while cfprefsd keeps serving it. sheng-dictation-prefs=1 restores the old write so the
 // two groups can be compared with a single image.
 // fuxi 2026-11-18: written by default again. -[UIKeyboardInputModeController isDictationLanguageEnabled:] (iPhone 21H16
 // UIKitCore 0x18a767234) reads the keyboard preference DictationLanguagesEnabled and calls updateEnabledDictationLanguages: (the
 // whole input-mode recomputation of the keyboard lag) whenever the queried language is not a key of that dictionary; without the
 // dictionary every query recomputes. sheng-dictation-prefs=0 goes back to the B-group cleanup.
 int optin=1;
 PE_parse_boot_argn("sheng-dictation-prefs",&optin,sizeof(optin));
 if(optin!=1)
  return fuxi_boot_dictation_cleanup(p,scratch);
 int on=0;int32_t result=0;
 if(!PE_parse_boot_argn("sheng-data-skel",&on,sizeof(on)) || on!=1)return 0;
 static const char *const paths[]={
  "/private/var/Managed Preferences/mobile/com.apple.Preferences.plist",
  "/private/var/Managed Preferences/mobile/com.apple.keyboard.preferences.plist"};

 int last=0;unsigned written=0,present=0;
 for(unsigned i=0;i<sizeof(paths)/sizeof(paths[0]);++i) {
  int error=copyout(paths[i],scratch,strlen(paths[i])+1);
  // Rewritten every boot (2026-11-14): the language list grew, and a file from an earlier boot keeps the old one.
  struct open_args op={.path=scratch,.flags=O_WRONLY|O_CREAT|O_TRUNC|O_NOFOLLOW,.mode=0644};
  if(!error)error=open(p,&op,&result);
  if(!error) {
   int fd=result;
   error=copyout(dictation_body,scratch+0x200,sizeof(dictation_body)-1);
   if(!error){struct write_args wr={.fd=fd,.cbuf=scratch+0x200,.nbyte=sizeof(dictation_body)-1};user_ssize_t n=0;error=write(p,&wr,&n);
    if(!error && n!=(user_ssize_t)(sizeof(dictation_body)-1))error=EIO;}
   if(!error){struct fchown_args own={.fd=fd,.uid=0,.gid=0};error=fchown(p,&own,&result);}
   struct close_args cl={.fd=fd};int ce=sys_close(p,&cl,&result);if(!error)error=ce;
   if(!error)++written;
  }
  if(error)last=error;
 }
 printf("fuxi dictation prefs: written %u present %u rc %d\n",written,present,last);
 return last;
}

// fuxi 2026-11-14 (experiment): GPU stalls (one hung FitnessWidget submission froze the UI: the reset left backboardd with a lost
// device and Turnip wrote through a NULL command stream) sat at Turnip's GMEM resolve. TU_DEBUG=sysmem for every Metal process
// (/private/var/ngpu/tu_debug, read by NativeAdrenoMetalPlugin.mm) renders without GMEM tiles and resolves. Rewritten every boot.
static int fuxi_boot_tu_debug(proc_t p,uint64_t scratch) {
 int32_t result=0;
 static const char dir[]="/private/var/ngpu";
 static const char path[]="/private/var/ngpu/tu_debug";
 static const char body[]="\n";   // 2026-11-15: sysmem did not stop the stalls; an empty TU_DEBUG (the file stays on Data)
 int error=copyout(dir,scratch,sizeof(dir));
 if(!error){struct mkdir_args md={.path=scratch,.mode=0755};error=mkdir(p,&md,&result);if(error==EEXIST)error=0;}
 if(!error)error=copyout(path,scratch,sizeof(path));
 int fd=-1;
 if(!error){struct open_args op={.path=scratch,.flags=O_WRONLY|O_CREAT|O_TRUNC|O_NOFOLLOW,.mode=0644};error=open(p,&op,&result);if(!error)fd=result;}
 if(!error)error=copyout(body,scratch+0x200,sizeof(body)-1);
 if(!error){struct write_args wr={.fd=fd,.cbuf=scratch+0x200,.nbyte=sizeof(body)-1};user_ssize_t n=0;error=write(p,&wr,&n);
  if(!error && n!=(user_ssize_t)(sizeof(body)-1))error=EIO;}
 if(fd>=0){struct close_args cl={.fd=fd};int ce=sys_close(p,&cl,&result);if(!error)error=ce;}
 printf("fuxi tu_debug: cleared rc %d\n",error);
 return error;
}


// fuxi 2026-11-17: China Standard Time. The Data skeleton (21H16 /private/var template) creates /private/var/db/timezone/localtime ->
// US/Pacific only when it is absent, so the stored Data kept Pacific time. Pointed at Asia/Shanghai at every boot (sheng-data-skel=1);
// fuxi-timezone=0 leaves the link alone.
// 2026-11-19: no longer tied to sheng-data-skel=1 (other people's packs do not set it, so their phones stayed on Pacific time), and
// the link is replaced only when it is missing or still the template's US/Pacific: a zone the user picked in Settings is kept.
// fuxi-timezone=2 forces Asia/Shanghai at every boot.
static int fuxi_boot_timezone(proc_t p,uint64_t scratch) {
 int want=1;int32_t result=0;
 PE_parse_boot_argn("fuxi-timezone",&want,sizeof(want));
 if(want!=1 && want!=2)return 0;
 static const char link[]="/private/var/db/timezone/localtime";
 static const char target[]="/var/db/timezone/zoneinfo/Asia/Shanghai";
 int error=copyout(link,scratch,sizeof(link));
 if(!error && want==1){
  struct readlink_args rl={.path=scratch,.buf=scratch+0x400,.count=0x100};
  int32_t n=0;
  if(!readlink(p,&rl,&n) && n>0 && n<0x100){
   char cur[0x100]={};
   if(!copyin(scratch+0x400,cur,(size_t)n)){
    cur[n]=0;
    if(!strnstr(cur,"US/Pacific",sizeof cur) && !strnstr(cur,"America/Los_Angeles",sizeof cur)){printf("fuxi timezone: kept %s\n",cur);return 0;}
   }
  }
 }
 if(!error){struct unlink_args rm={.path=scratch};error=unlink(p,&rm,&result);if(error==ENOENT)error=0;}
 if(!error)error=copyout(target,scratch+0x200,sizeof(target));
 if(!error){struct symlink_args sl={.path=scratch+0x200,.link=scratch};error=symlink(p,&sl,&result);}
 if(!error){struct lchown_args own={.path=scratch,.owner=0,.group=0};error=lchown(p,&own,&result);}
 printf("fuxi timezone: localtime -> Asia/Shanghai rc %d\n",error);
 return error;
}


// fuxi 2026-11-18: keyboard lag root cause (whole-stack hot sampler, symbolized with the iPhone 21H16 arm64e cache): every
// -[UIKeyboardInputMode dictationLanguage] goes through activeInputModes -> enabledInputModeIdentifiers:, which, with no
// AppleKeyboards in the global domain (Setup never ran, Setup writes it), falls back to defaultEnabledInputModesForCurrentLocale and
// recomputes all input modes of the locale (TIGetDefaultInputModesForLanguage, NSArray indexOfObject: over every supported mode): the
// app's main thread at 100 % while the keyboard is up. A managed .GlobalPreferences gives the list. Rewritten at every boot
// (sheng-data-skel=1); fuxi-keyboards=0 leaves it out (the managed value wins over Settings > Keyboards).
static const char keyboards_body[] =
  "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
  "<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n"
  "<plist version=\"1.0\"><dict>"
  "<key>AppleKeyboards</key><array>"
  "<string>zh_Hans-Pinyin@sw=Pinyin-Simplified;hw=Automatic</string>"
  "<string>en_US@sw=QWERTY;hw=Automatic</string>"
  "<string>emoji@sw=Emoji</string>"
  "</array>"
  "<key>AppleKeyboardsExpanded</key><integer>1</integer>"
  "</dict></plist>\n";
static int fuxi_boot_keyboards(proc_t p,uint64_t scratch) {
 int on=0,want=1;int32_t result=0;
 if(!PE_parse_boot_argn("sheng-data-skel",&on,sizeof(on)) || on!=1)return 0;
 PE_parse_boot_argn("fuxi-keyboards",&want,sizeof(want));
 if(want!=1){printf("fuxi keyboards: skipped\n");return 0;}
 static const char path[]="/private/var/Managed Preferences/mobile/.GlobalPreferences.plist";
 int error=copyout(path,scratch,sizeof(path));
 int fd=-1;
 if(!error){struct open_args op={.path=scratch,.flags=O_WRONLY|O_CREAT|O_TRUNC|O_NOFOLLOW,.mode=0644};error=open(p,&op,&result);if(!error)fd=result;}
 if(!error)error=copyout(keyboards_body,scratch+0x200,sizeof(keyboards_body)-1);
 if(!error){struct write_args wr={.fd=fd,.cbuf=scratch+0x200,.nbyte=sizeof(keyboards_body)-1};user_ssize_t n=0;error=write(p,&wr,&n);
  if(!error && n!=(user_ssize_t)(sizeof(keyboards_body)-1))error=EIO;}
 if(!error){struct fchown_args own={.fd=fd,.uid=0,.gid=0};error=fchown(p,&own,&result);}
 if(fd>=0){struct close_args cl={.fd=fd};int ce=sys_close(p,&cl,&result);if(!error)error=ce;}
 printf("fuxi keyboards: managed AppleKeyboards rc %d\n",error);
 return error;
}

// fuxi 2026-11-19: Settings showed "No Internet Connection" on a Wi-Fi that works (DNS answers, TLS to Apple completes): the captive
// portal probe was never sent, so the network stayed unevaluated. A managed com.apple.captive.control with Active false (the key
// configd's captive agent reads) turns the probe off and the network counts as reachable. fuxi-captive=1 leaves the probe on.
static const char captive_body[] =
  "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
  "<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n"
  "<plist version=\"1.0\"><dict><key>Active</key><false/></dict></plist>\n";
static int fuxi_boot_captive(proc_t p,uint64_t scratch) {
 int on=0,want=0;int32_t result=0;
 if(!PE_parse_boot_argn("sheng-data-skel",&on,sizeof(on)) || on!=1)return 0;
 PE_parse_boot_argn("fuxi-captive",&want,sizeof(want));
 if(want==1){printf("fuxi captive: probe left on\n");return 0;}
 static const char path[]="/private/var/Managed Preferences/mobile/com.apple.captive.control.plist";
 int error=copyout(path,scratch,sizeof(path));
 int fd=-1;
 if(!error){struct open_args op={.path=scratch,.flags=O_WRONLY|O_CREAT|O_TRUNC|O_NOFOLLOW,.mode=0644};error=open(p,&op,&result);if(!error)fd=result;}
 if(!error)error=copyout(captive_body,scratch+0x200,sizeof(captive_body)-1);
 if(!error){struct write_args wr={.fd=fd,.cbuf=scratch+0x200,.nbyte=sizeof(captive_body)-1};user_ssize_t n=0;error=write(p,&wr,&n);
  if(!error && n!=(user_ssize_t)(sizeof(captive_body)-1))error=EIO;}
 if(!error){struct fchown_args own={.fd=fd,.uid=0,.gid=0};error=fchown(p,&own,&result);}
 if(fd>=0){struct close_args cl={.fd=fd};int ce=sys_close(p,&cl,&result);if(!error)error=ce;}
 printf("fuxi captive: managed probe off rc %d\n",error);
 return error;
}

// fuxi 2026-11-19: LaunchServices' store dropped at every boot (fuxi-ls-rebuild=0 keeps it), so lsd builds it again. WebContent
// passes _container_init on the first boot after a wipe and fails it ("could not create xpc_pipe") on every later boot; upstream
// (patches/xnu/zzyb-native-cryptex-os-view.patch, native_ls_store_drop) found lsd not registering system content again on a later
// boot of the same OS build. The store lives in an InternalDaemon container whose UUID changes with every wipe, so each container's
// Library/Caches is searched for com.apple.LaunchServices-* files. Reports the files removed.
static unsigned fuxi_dir_names(const char *dir, const char *prefix, char (*names)[96], unsigned max, int dirs_only) {
 vfs_context_t ctx = vfs_context_current();
 vnode_t vp = NULLVP;
 if (vnode_lookup(dir, 0, &vp, ctx)) return 0;
 unsigned found = 0;
 char *buffer = kalloc_data(4096, Z_WAITOK);
 uio_t uio = buffer ? uio_create(1, 0, UIO_SYSSPACE, UIO_READ) : NULL;
 int eof = 0;
 const size_t plen = strlen(prefix);
 while (uio && !eof && found < max) {
  uio_reset(uio, uio_offset(uio), UIO_SYSSPACE, UIO_READ);
  uio_addiov(uio, CAST_USER_ADDR_T(buffer), 4096);
  int entries = 0;
  if (VNOP_READDIR(vp, uio, 0, &eof, &entries, ctx)) break;
  const size_t used = 4096 - (size_t)uio_resid(uio);
  if (!used) break;
  for (size_t at = 0; at + offsetof(struct dirent, d_name) <= used && found < max;) {
   const struct dirent *e = (const struct dirent *)(buffer + at);
   if (!e->d_reclen) break;
   const int is_dir = e->d_type == DT_DIR;
   if (e->d_namlen < 96 && e->d_name[0] != '.' && (!dirs_only || is_dir) && !strncmp(e->d_name, prefix, plen)) {
    memcpy(names[found], e->d_name, e->d_namlen);
    names[found++][e->d_namlen] = 0;
   }
   at += e->d_reclen;
  }
 }
 if (uio) uio_free(uio);
 if (buffer) kfree_data(buffer, 4096);
 vnode_put(vp);
 return found;
}
static void fuxi_boot_ls_drop(proc_t p, uint64_t scratch) {
 int on = 0, want = 1;
 if (!PE_parse_boot_argn("sheng-data-skel", &on, sizeof(on)) || on != 1) return;
 PE_parse_boot_argn("fuxi-ls-rebuild", &want, sizeof(want));
 if (want != 1) {printf("fuxi ls store: kept\n"); return;}
 static const char base[] = "/private/var/mobile/Containers/Data/InternalDaemon";
 // On the heap: static tables pushed the kernel __DATA past its prelink room.
 char (*containers)[96] = kalloc_data(48 * 96, Z_WAITOK | Z_ZERO);
 char (*files)[96] = kalloc_data(8 * 96, Z_WAITOK | Z_ZERO);
 if (!containers || !files) {
  if (containers) kfree_data(containers, 48 * 96);
  if (files) kfree_data(files, 8 * 96);
  printf("fuxi ls store: no memory\n"); return;
 }
 char path[300];
 const unsigned n = fuxi_dir_names(base, "", containers, 48, 1);
 int removed = 0, failed = 0;
 for (unsigned i = 0; i < n; ++i) {
  snprintf(path, sizeof(path), "%s/%s/Library/Caches", base, containers[i]);
  const unsigned m = fuxi_dir_names(path, "com.apple.LaunchServices-", files, 8, 0);
  for (unsigned k = 0; k < m; ++k) {
   char file[400];
   snprintf(file, sizeof(file), "%s/%s", path, files[k]);
   struct unlink_args ul = {.path = scratch + 0x200};
   int32_t result = 0;
   int error = copyout(file, scratch + 0x200, strlen(file) + 1);
   if (!error) error = unlink(p, &ul, &result);
   if (error) failed++; else removed++;
   printf("fuxi ls store: %s %s rc %d\n", containers[i], files[k], error);
  }
 }
 printf("fuxi ls store: %u containers, %d removed, %d failed\n", n, removed, failed);
 kfree_data(containers, 48 * 96);
 kfree_data(files, 8 * 96);
}

// fuxi 2026-11-20 (U13 test): Safari's WebContent is refused the containermanagerd lookup (launchd error 159) from the second boot
// after a wipe only, so state kept on Data is suspected. The launchd state directory and containermanagerd's stores are renamed to
// <name>.fuxi-asideN (never deleted) so both start fresh as after a wipe. Default on in this build; fuxi-state-aside=0 skips it.
static void fuxi_boot_state_aside(proc_t p, uint64_t scratch) {
 // U13 result (2026-11-20): all three moved, WebContent still refused with 159, so this is not the cause. Off by default now.
 int want = 0;
 PE_parse_boot_argn("fuxi-state-aside", &want, sizeof(want));
 if (want != 1) {printf("fuxi state aside: off\n"); return;}
 static const char *const dirs[] = {
  "/private/var/db/com.apple.xpc.launchd",
  "/private/var/root/Library/MobileContainerManager",
  "/private/var/mobile/Library/MobileContainerManager",
  "/private/var/containers/Data/System/com.apple.containermanagerd",
 };
 for (unsigned i = 0; i < sizeof(dirs) / sizeof(dirs[0]); ++i) {
  int error = ENOENT;
  char to[160];
  for (unsigned n = 1; n <= 9; ++n) {
   snprintf(to, sizeof(to), "%s.fuxi-aside%u", dirs[i], n);
   int32_t result = 0;
   error = copyout(dirs[i], scratch, strlen(dirs[i]) + 1);
   if (!error) error = copyout(to, scratch + 0x200, strlen(to) + 1);
   if (error) break;
   struct rename_args rn = {.from = scratch, .to = scratch + 0x200};
   error = rename(p, &rn, &result);
   if (error != EEXIST && error != ENOTEMPTY) break;
  }
  printf("fuxi state aside: %s -> %s rc %d\n", dirs[i], error ? "-" : to, error);
 }
}

// One comma-separated label at *c into the policy as a disabled key; advances *c past it.
static int append_job(const char **cursor) {
 const char *c=*cursor,*e=c;while(*e && *e!=',')++e;
 if(e>c) {
  if(strlcat(policy,"<key>",sizeof(policy))>=sizeof(policy))return EINVAL;
  size_t at=strlen(policy);if(at+(size_t)(e-c)+1>=sizeof(policy))return EINVAL;
  memcpy(policy+at,c,(size_t)(e-c));policy[at+(size_t)(e-c)]=0;
  if(strlcat(policy,"</key><true/>",sizeof(policy))>=sizeof(policy))return EINVAL;
 }
 *cursor=*e?e+1:e;return 0;
}

int sheng_boot_watchdog_policy(void *process, uint64_t scratch) {
 proc_t p=process;
 int enabled=0,error=0,fd=-1;int32_t result=0;
 PE_parse_boot_argn("sheng-disable-watchdogd",&enabled,sizeof(enabled));
 if(!PE_parse_boot_argn("sheng-disable-jobs",jobs,sizeof(jobs)))jobs[0]=0;jobs[sizeof(jobs)-1]=0;
 int lite=0;PE_parse_boot_argn("sheng-lite",&lite,sizeof(lite));if(lite!=1)lite=0;
 if(enabled!=1)enabled=0;
 for(const char *c=jobs;*c;++c)if(!((*c>='a'&&*c<='z')||(*c>='A'&&*c<='Z')||(*c>='0'&&*c<='9')||*c=='.'||*c=='-'||*c==','))return EINVAL;
 int setup=0,reset=0;
 PE_parse_boot_argn("sheng-setup",&setup,sizeof(setup));
 PE_parse_boot_argn("sheng-data-reset",&reset,sizeof(reset));   // 2 = erase Data and show the Hello page; 1 = erase Data, Setup stays skipped
 if(reset==2)setup=1;
 if(setup==1 && (error=sheng_boot_setup_reset(p,scratch))) {
  sheng_watchdog_policy_status=error;
  printf("sheng setup flags reset failed: %d\n",error);
  return error;
 }
 if(setup==1)printf("sheng setup flags reset: Hello page on this boot\n");
 // Independent of the launch policy below: report and continue on failure.
 (void)sheng_boot_data_skel(p,scratch);
 (void)sheng_boot_keychains(p,scratch);
 (void)fuxi_boot_dictation_prefs(p,scratch);
 (void)fuxi_boot_dictation_off(p,scratch);
 (void)fuxi_boot_tu_debug(p,scratch);
 (void)fuxi_boot_timezone(p,scratch);
 (void)fuxi_boot_keyboards(p,scratch);
 (void)fuxi_boot_captive(p,scratch);
 fuxi_boot_ls_drop(p,scratch);
 fuxi_boot_state_aside(p,scratch);
 // fuxi (2026-11-14): fairplayd.H2 needs the Apple AES engine's UID/GID keys (FairPlayIOKit generateSeed through
 // IOAESAccelerator::performAES), which this SoC does not have, so it exits at every start without checking in its Mach
 // services; launchd keeps com.apple.fairplayd.versioned, locationd's migration call waits on it forever and data
 // migration (datamigrator) never finishes. Disabled, the lookup fails at once and the migration plugins return.
 // sheng-fairplay=1 leaves it enabled.
 int fairplay=0;PE_parse_boot_argn("sheng-fairplay",&fairplay,sizeof(fairplay));
 const int no_fairplay=fairplay!=1;
 if(!enabled && !jobs[0] && !lite && !no_fairplay)return 0;
 policy[0]=0;strlcat(policy,policy_head,sizeof(policy));
 if(enabled)strlcat(policy,policy_watchdogd,sizeof(policy));
 if(no_fairplay)strlcat(policy,"<key>com.apple.fairplayd.H2</key><true/>",sizeof(policy));
 if(lite)for(const char *c=lite_jobs;*c;) {if((error=append_job(&c)))return error;}
 for(const char *c=jobs;*c;) {if((error=append_job(&c)))return error;}
 strlcat(policy,policy_tail,sizeof(policy));
 const char *directory="/private/var/db/com.apple.xpc.launchd";
 const char *path="/private/var/db/com.apple.xpc.launchd/disabled.plist";
 if((error=copyout(directory,scratch,strlen(directory)+1)))goto done;
 struct mkdir_args md={.path=scratch,.mode=0755};
 error=mkdir(p,&md,&result);
 if(error && error!=EEXIST)goto done;
 if((error=copyout(path,scratch,strlen(path)+1)))goto done;
 // With persistent Data the previous boot's file is there: this policy is rewritten in place on every boot (it must follow the
 // boot arguments). Symlinks are still refused (O_NOFOLLOW) and the fstat check below insists on a root-owned regular file.
 struct open_args op={.path=scratch,.flags=O_WRONLY|O_CREAT|O_TRUNC|O_NOFOLLOW,.mode=0644};
 if((error=open(p,&op,&result)))goto done;
 fd=result;
 // The scratch page keeps the cache-mount environment slots at +0x400, so the policy (the lite list makes it longer than 0x200 bytes) goes
 // out in pieces through the 0x200 bytes at +0x200.
 for(size_t sent=0,total=strlen(policy);sent<total;) {
  size_t piece=total-sent<0x1f0?total-sent:0x1f0;
  if((error=copyout(policy+sent,scratch+0x200,piece)))goto done;
  struct write_args wr={.fd=fd,.cbuf=scratch+0x200,.nbyte=piece};
  user_ssize_t written=0;
  if((error=write(p,&wr,&written)))goto done;
  if(written!=(user_ssize_t)piece){error=EIO;goto done;}
  sent+=piece;
 }
 struct fchown_args owner={.fd=fd,.uid=0,.gid=0};
 if((error=fchown(p,&owner,&result)))goto done;
 struct fchmod_args mode={.fd=fd,.mode=0644};
 if((error=fchmod(p,&mode,&result)))goto done;
 struct fsync_args sync={.fd=fd};
 if((error=fsync(p,&sync,&result)))goto done;
 // Preserve the cache-mount environment slots at +0x400, +0x500, +0x600.
 struct fstat64_args sa={.fd=fd,.ub=scratch+0x800};struct stat64 st={0};
 if((error=sys_fstat64(p,&sa,&result)) || (error=copyin(sa.ub,&st,sizeof(st))))goto done;
 if(st.st_uid!=0 || st.st_gid!=0 || !S_ISREG(st.st_mode) || (st.st_mode&0777)!=0644 || st.st_size!=(off_t)(strlen(policy)))error=EINVAL;
 done:
 if(fd>=0){struct close_args cl={.fd=fd};int e=sys_close(p,&cl,&result);if(!error)error=e;}
 // A real empty migration marker selects the qualified modern override loader.
 if(!error) {
  const char *marker="/private/var/db/com.apple.xpc.launchd/disabled.migrated";
  error=copyout(marker,scratch,strlen(marker)+1);
  if(!error) {
   struct open_args mark={.path=scratch,.flags=O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW,.mode=0644};
   error=open(p,&mark,&result);
   if(!error){struct close_args cl={.fd=result};error=sys_close(p,&cl,&result);}
   else if(error==EEXIST)error=0;
  }
 }
 sheng_watchdog_policy_status=error;
 printf("sheng bring-up watchdogd launch policy: %d (hardware watchdog not implemented)\n",error);
 return error;
}
